def build_scene():
    clear_scene()

    floor_mat = make_material("floor_mat", "interior_tiles_diff_4k.jpg", 0.0000, 0.9000, (1.0000, 1.0000, 1.0000))
    build_mesh_object("Floor", FLOOR_POSITIONS, FLOOR_UVS, FLOOR_INDICES, floor_mat)

    mirror_mat = make_material("mirror_mat", None, 1.0000, 0.0200, (0.9200, 0.9200, 0.9500))
    build_mesh_object("Mirror", MIRROR_POSITIONS, MIRROR_UVS, MIRROR_INDICES, mirror_mat)

    duck_mat = make_material("duck_mat", "DuckCM.png", 0.0000, 0.4000, (1.0000, 1.0000, 1.0000))
    build_mesh_object("Duck", DUCK_POSITIONS, DUCK_UVS, DUCK_INDICES, duck_mat)

    add_sun((-0.0, 0.707107, -0.707107), 3.0000)
    setup_world((0.53, 0.81, 0.98), 0.4000)

    bpy.context.scene.render.resolution_x = 1920
    bpy.context.scene.render.resolution_y = 1080
    bpy.context.scene.render.resolution_percentage = 100

    cameras = {}
    cameras['main_shot'] = add_camera('main_shot', (2.03691, -7.45042, 2.32992), (-0.291363, 0.933623, -0.20846), (-0.062102, 0.198994, 0.978031), 1.0471975512, 0.1000, 300.0000)
    cameras['duck_closeup'] = add_camera('duck_closeup', (3.13741, -1.10318, 1.52779), (-0.959686, 0.051195, -0.276374), (-0.275981, 0.014722, 0.96105), 1.0471975512, 0.1000, 300.0000)
    cameras['shadow_closeup'] = add_camera('shadow_closeup', (1.38622, -0.32333, 1.86885), (-0.550766, 0.007323, -0.834628), (-0.834555, 0.011056, 0.550814), 1.0471975512, 0.1000, 300.0000)
    cameras['reflection_closeup'] = add_camera('reflection_closeup', (-0.325579, 6.7632, 2.13806), (-0.919535, 0.339094, -0.198674), (-0.1864, 0.068748, 0.980066), 1.0471975512, 0.1000, 300.0000)
    return cameras


def render_all(cameras, output_dir):
    os.makedirs(output_dir, exist_ok=True)
    scene = bpy.context.scene
    for name, cam_obj in cameras.items():
        scene.camera = cam_obj
        scene.render.filepath = os.path.join(output_dir, name + ".png")
        bpy.ops.render.render(write_still=True)


if __name__ == "__main__":
    cams = build_scene()
    argv = sys.argv[sys.argv.index("--") + 1 :] if "--" in sys.argv else []
    if "--render-all" in argv:
        render_all(cams, os.path.join(SCRIPT_DIR, "renders"))
